#!/bin/sh
# Restore an explicit COPY of the reviewed KernelSU files to its pinned baseline.
set -eu
[ "$#" -eq 1 ] || { printf 'usage: ROLLBACK-autostart.sh /absolute/path/to/kernel-source-copy\n' >&2; exit 2; }
case "$1" in /*) ;; *) printf 'absolute copy path required\n' >&2; exit 2 ;; esac
python3 - "$1" <<'PYROLLBACK'
import base64, gzip, hashlib, json, pathlib, sys
root=pathlib.Path(sys.argv[1])
if root.is_symlink() or not root.is_dir(): raise SystemExit('source copy must be a directory')
baseline=json.loads(gzip.decompress(base64.b64decode('')))
for relative, encoded in baseline.items():
    path=root / relative
    if not path.is_file() or path.is_symlink(): raise SystemExit('regular source files required')
for relative, encoded in baseline.items():
    path=root / relative
    data=base64.b64decode(encoded)
    path.write_bytes(data)
    assert path.read_bytes()==data
    print(f'Restored {relative} sha256={hashlib.sha256(data).hexdigest()}')
PYROLLBACK
